use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn is_zero_f64(x: f64) -> bool {
    x == 0.0f64
}

fn hermeline(off: f64, scl: f64) -> (coeffs: Vec<f64>)
    ensures
        coeffs@.len() == 2,
        coeffs@[0] == off,
        coeffs@[1] == scl,
        is_zero_f64(scl) ==> coeffs@[1] == 0.0f64
{
    let mut v = Vec::new();
    
    // Push the first element (off)
    v.push(off);
    
    // Push the second element with special handling for zero case
    let second_elem = if scl == 0.0f64 {
        0.0f64
    } else {
        scl
    };
    v.push(second_elem);
    
    // Verify the postconditions
    proof {
        // Vector has exactly 2 elements
        assert(v@.len() == 2);
        
        // First element equals off
        assert(v@[0] == off);
        
        // Second element equals scl (or 0.0 if scl is zero)
        if scl == 0.0f64 {
            assert(v@[1] == 0.0f64);
            assert(v@[1] == scl); // 0.0 == 0.0
        } else {
            assert(v@[1] == scl);
        }
    }
    
    v
}

} // verus!

fn main() {
    // Test cases
    let v1 = hermeline(1.5, 2.5);
    println!("Test 1: off=1.5, scl=2.5 -> [{}, {}]", v1[0], v1[1]);
    
    let v2 = hermeline(3.0, 0.0);
    println!("Test 2: off=3.0, scl=0.0 -> [{}, {}]", v2[0], v2[1]);
    
    let v3 = hermeline(-1.0, -0.0);
    println!("Test 3: off=-1.0, scl=-0.0 -> [{}, {}]", v3[0], v3[1]);
}